"""Oracle DB-API database gateway and idempotent EventForge schema."""
from __future__ import annotations
import os
from contextlib import contextmanager
from typing import Iterator
try:
    import oracledb
except ImportError:  # module can still be imported by pure unit tests
    oracledb = None

# DDL is deliberately owned by the executable runtime; ORA-00955 means it exists.
SCHEMA = [
"CREATE TABLE eventforge_users (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR2(320) UNIQUE NOT NULL, password_hash VARCHAR2(512) NOT NULL, display_name VARCHAR2(120) NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)",
"CREATE TABLE eventforge_events (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id NUMBER NOT NULL, name VARCHAR2(200) NOT NULL, event_datetime TIMESTAMP WITH TIME ZONE NOT NULL, venue VARCHAR2(300), capacity NUMBER, budget_limit NUMBER(18,2) DEFAULT 0 NOT NULL, status VARCHAR2(30) DEFAULT 'DRAFT' NOT NULL, description CLOB, confirmed_guest_count NUMBER DEFAULT 0 NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)",
"CREATE TABLE eventforge_tasks (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id NUMBER NOT NULL, title VARCHAR2(300) NOT NULL, description CLOB, status VARCHAR2(30) DEFAULT 'TODO' NOT NULL, deadline TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)",
"CREATE TABLE eventforge_task_dependencies (task_id NUMBER NOT NULL, dependency_id NUMBER NOT NULL, PRIMARY KEY(task_id, dependency_id))",
"CREATE TABLE eventforge_invitations (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id NUMBER NOT NULL, guest_name VARCHAR2(200) NOT NULL, guest_email VARCHAR2(320) NOT NULL, status VARCHAR2(20) DEFAULT 'PENDING' NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)",
"CREATE TABLE eventforge_categories (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id NUMBER NOT NULL, name VARCHAR2(200) NOT NULL, planned_amount NUMBER(18,2) DEFAULT 0 NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)",
"CREATE TABLE eventforge_expenses (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id NUMBER NOT NULL, category_id NUMBER NOT NULL, description VARCHAR2(500) NOT NULL, amount NUMBER(18,2) NOT NULL, expenditure_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)",
"CREATE TABLE eventforge_schedule (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id NUMBER NOT NULL, title VARCHAR2(300) NOT NULL, start_time TIMESTAMP WITH TIME ZONE NOT NULL, end_time TIMESTAMP WITH TIME ZONE NOT NULL, details CLOB, created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)",
"CREATE TABLE eventforge_vendors (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id NUMBER NOT NULL, name VARCHAR2(200) NOT NULL, service_type VARCHAR2(120) NOT NULL, contact_name VARCHAR2(200) NOT NULL, contact_email VARCHAR2(320) NOT NULL, booking_reference VARCHAR2(200) NOT NULL, cost NUMBER(18,2) NOT NULL, paid_amount NUMBER(18,2) DEFAULT 0 NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)",
"CREATE TABLE eventforge_payments (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id NUMBER NOT NULL, vendor_id NUMBER NOT NULL, amount NUMBER(18,2) NOT NULL, payment_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, note VARCHAR2(500), created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)",
"CREATE TABLE eventforge_notifications (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id NUMBER NOT NULL, notification_type VARCHAR2(40) NOT NULL, message VARCHAR2(1000) NOT NULL, is_read NUMBER(1) DEFAULT 0 NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)",
"CREATE TABLE eventforge_activity (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id NUMBER NOT NULL, actor_user_id NUMBER NOT NULL, action VARCHAR2(100) NOT NULL, details CLOB, created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)",
]
class OracleDatabase:
    def __init__(self, dsn:str, user:str, password:str): self.dsn,self.user,self.password=dsn,user,password
    @contextmanager
    def transaction(self)->Iterator[object]:
        if oracledb is None: raise RuntimeError('python-oracledb is not installed')
        con=oracledb.connect(user=self.user,password=self.password,dsn=self.dsn)
        try:
            yield con; con.commit()
        except BaseException:
            con.rollback(); raise
        finally: con.close()
    def bootstrap(self)->None:
        with self.transaction() as con:
            cur=con.cursor()
            for ddl in SCHEMA:
                try: cur.execute(ddl)
                except oracledb.DatabaseError as exc:
                    if getattr(exc.args[0], 'code', None)!=955: raise
            cur.close()
def database_from_environment()->OracleDatabase:
    return OracleDatabase(os.getenv('ORACLE_DSN','localhost:1521/FREEPDB1'),os.getenv('ORACLE_USER','eventforge'),os.getenv('ORACLE_PASSWORD',''))
